// TestAndPollMethodsSucceed exercises every *AndPoll method end-to-end against
// the fake task flow and asserts each completes without error. This guards the
// wiring of the isolated custom code: action -> poll task -> (extract created
// resource) -> get.
func TestAndPollMethodsSucceed(t *testing.T) {
	server := newTaskFlowServer(taskFlowConfig{})
	defer server.Close()
	client := newTaskFlowClient(server)

	for _, tc := range andPollMethods {
		t.Run(tc.name, func(t *testing.T) {
			if err := tc.invoke(context.Background(), client); err != nil {
				t.Fatalf("%s returned an unexpected error: %s", tc.name, err)
			}
		})
	}
}

// TestAndPollMethodsCount is a canary: if codegen or a spec change adds/removes
// an *AndPoll method, this reminds us to keep the table in sync.
func TestAndPollMethodsCount(t *testing.T) {
	const want = 93
	if got := len(andPollMethods); got != want {
		t.Fatalf("andPollMethods has %d entries, want %d; update the table in this file", got, want)
	}
}

// TestNewAndPollRequiresTask verifies a NewAndPoll method surfaces an error when
// the API creates no task (a New must always create exactly one).
func TestNewAndPollRequiresTask(t *testing.T) {
	empty := []string{}
	server := newTaskFlowServer(taskFlowConfig{actionTasks: &empty})
	defer server.Close()
	client := newTaskFlowClient(server)

	if _, err := client.Cloud.FloatingIPs.NewAndPoll(context.Background(), cloud.FloatingIPNewParams{}); err == nil {
		t.Fatal("NewAndPoll with no created task should return an error")
	}
}

// TestTaskServicePoll covers the shared TaskService.Poll loop that every
// *AndPoll method relies on.
func TestTaskServicePoll(t *testing.T) {
	t.Run("finished", func(t *testing.T) {
		server := newTaskFlowServer(taskFlowConfig{taskState: cloud.TaskStateFinished})
		defer server.Close()
		client := newTaskFlowClient(server)

		task, err := client.Cloud.Tasks.Poll(context.Background(), "task-1")
		if err != nil {
			t.Fatalf("Poll returned an unexpected error: %s", err)
		}
		if task.State != cloud.TaskStateFinished {
			t.Fatalf("Poll returned state %q, want FINISHED", task.State)
		}
	})

	t.Run("error", func(t *testing.T) {
		server := newTaskFlowServer(taskFlowConfig{taskState: cloud.TaskStateError, taskError: "boom"})
		defer server.Close()
		client := newTaskFlowClient(server)

		_, err := client.Cloud.Tasks.Poll(context.Background(), "task-1")
		if err == nil {
			t.Fatal("Poll should return an error for a task in ERROR state")
		}
		if !strings.Contains(err.Error(), "boom") {
			t.Fatalf("Poll error %q should mention the task error %q", err.Error(), "boom")
		}
	})

	t.Run("context timeout", func(t *testing.T) {
		// Task never reaches a terminal state, so Poll loops until the context
		// deadline. The min polling interval is 1s, so a short deadline wins
		// deterministically after the first status check.
		server := newTaskFlowServer(taskFlowConfig{taskState: cloud.TaskStateRunning})
		defer server.Close()
		client := newTaskFlowClient(server)

		ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
		defer cancel()
		_, err := client.Cloud.Tasks.Poll(ctx, "task-1")
		if !errors.Is(err, context.DeadlineExceeded) {
			t.Fatalf("Poll error = %v, want context.DeadlineExceeded", err)
		}
	})
}
